#!/usr/bin/env node
// Generates catalog/agents.json, catalog/CATALOG.md and docs/AGENT-CAPABILITIES.md from agents/ and catalog/roster.json.
// Usage: node scripts/build-catalog.mjs [--check]   (--check exits 1 if generated files are stale)
import { existsSync, mkdirSync, readFileSync, readdirSync, statSync, writeFileSync } from "node:fs";
import { dirname, join, relative } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
const check = process.argv.includes("--check");

function parse(text) {
  const m = text.replace(/\r\n/g, "\n").match(/^---\n([\s\S]*?)\n---\n?([\s\S]*)$/);
  if (!m) return null;
  const f = {};
  for (const line of m[1].split("\n")) {
    const kv = line.match(/^([A-Za-z][\w-]*):\s*(.*)$/);
    if (!kv) continue;
    let v = kv[2].trim();
    v = v.startsWith("[") && v.endsWith("]") ? v.slice(1, -1).split(",").map((s) => s.trim()).filter(Boolean) : v.replace(/^["']|["']$/g, "");
    f[kv[1]] = v;
  }
  return { f, body: m[2] };
}
const walk = (d, o = []) => { if (!existsSync(d)) return o; for (const e of readdirSync(d).sort()) { const p = join(d, e); statSync(p).isDirectory() ? walk(p, o) : e.endsWith(".md") && o.push(p); } return o; };

const roster = JSON.parse(readFileSync(join(ROOT, "catalog/roster.json"), "utf8"));
const planned = new Map();
for (const folders of Object.values(roster.streams)) for (const [folder, list] of Object.entries(folders)) for (const e of list) {
  const [name, runtime, model] = e.split(":"); planned.set(name, { folder, runtime, model });
}
const agents = [];
for (const path of walk(join(ROOT, "agents"))) {
  const p = parse(readFileSync(path, "utf8")); if (!p || !p.f.name) continue;
  const rel = relative(ROOT, path).replace(/\\/g, "/");
  const folder = dirname(rel).replace(/^agents\/?/, "");
  const skills = [...(p.body.match(/## Skills\n([\s\S]*?)(?=\n## |$)/)?.[1] || "").matchAll(/skills\/([a-z0-9-]+)\/SKILL\.md/g)].map((m) => m[1]);
  agents.push({ name: p.f.name, id: `npc-union:${folder.replace(/\//g, ":")}:${p.f.name}`, path: rel, folder, persona_name: p.f.persona_name || "", division: p.f.division || "", department: p.f.department || "", runtime: p.f.runtime || "claude", model: p.f.model || "", reasoning: p.f.reasoning || "", capabilities: Array.isArray(p.f.capabilities) ? p.f.capabilities : [], description: p.f.description || "", skills: [...new Set(skills)], status: "written" });
}
const written = new Set(agents.map((a) => a.name));
for (const [name, s] of planned) if (!written.has(name)) agents.push({ name, id: `npc-union:${s.folder.replace(/\//g, ":")}:${name}`, path: `agents/${s.folder}/${name}.md`, folder: s.folder, persona_name: "", division: s.folder.split("/")[0], department: s.folder.split("/").pop(), runtime: s.runtime, model: s.model, reasoning: "", capabilities: [], description: "", skills: [], status: "planned" });
agents.sort((a, b) => a.folder.localeCompare(b.folder) || a.name.localeCompare(b.name));

const json = JSON.stringify({ _generated: "by scripts/build-catalog.mjs; do not edit", count: agents.length, written: written.size, agents }, null, 2) + "\n";
const byFolder = Object.groupBy ? Object.groupBy(agents, (a) => a.folder) : agents.reduce((m, a) => ((m[a.folder] ||= []).push(a), m), {});
let md = `# NPC Union catalog\n\nGenerated by \`scripts/build-catalog.mjs\`. ${written.size} of ${agents.length} roster agents written.\n`;
for (const [folder, list] of Object.entries(byFolder)) {
  md += `\n## ${folder}\n\n| Persona | Agent | Runtime | Model | Description |\n|---|---|---|---|---|\n`;
  for (const a of list) md += `| ${a.persona_name || "(planned)"} | \`${a.id}\` | ${a.runtime} | ${a.model} | ${a.description.replace(/\|/g, "\\|")} |\n`;
}
let caps = `# Agent capabilities\n\nGenerated by \`scripts/build-catalog.mjs\` from agent frontmatter. Planned agents show roster values only.\n\n| Agent | Folder | Runtime | Model | Reasoning | Capabilities | Status |\n|---|---|---|---|---|---|---|\n`;
for (const a of agents) caps += `| ${a.name} | ${a.folder} | ${a.runtime} | ${a.model} | ${a.reasoning || "-"} | ${a.capabilities.join(", ") || "-"} | ${a.status} |\n`;

const outputs = { "catalog/agents.json": json, "catalog/CATALOG.md": md, "docs/AGENT-CAPABILITIES.md": caps };
let stale = [];
for (const [rel, content] of Object.entries(outputs)) {
  const full = join(ROOT, rel);
  if (check) { if (!existsSync(full) || readFileSync(full, "utf8") !== content) stale.push(rel); continue; }
  mkdirSync(dirname(full), { recursive: true }); writeFileSync(full, content);
}
if (check) { if (stale.length) { console.log(`Stale: ${stale.join(", ")}. Run node scripts/build-catalog.mjs`); process.exit(1); } console.log("Catalog is fresh"); }
else console.log(`Wrote ${Object.keys(outputs).join(", ")} (${written.size}/${agents.length} written)`);
